from questions._util import AWESOME, BLUE, VAULT, q

QUESTIONS = [
    q("cicd-git", "easy", "A secret landed in a commit that is already on the remote. Deleting the file in a new commit is not enough because:", "The secret remains in the history anyone can clone.", "Git rewrites old blobs when you delete a file.", "Remotes only store the latest tree.", "A force push of one empty commit erases every blob.", "Rotate the secret first. History rewrite is a second, coordinated step."),
    q("cicd-git", "medium", "main is protected and you need a reviewed change. What is the point of the protection?", "The branch that deploys cannot be rewritten or updated without the review you required.", "It makes git faster.", "It encrypts the repository.", "It blocks all tags.", "Protection is a policy on the remote. It is not a property of the commits themselves."),
    q("cicd-git", "medium", "You rebased a branch that a colleague had pulled. What did you change?", "The commit hashes. Their copy of the branch is now a different history.", "Only the commit messages. Hashes are stable across rebase.", "Nothing, if the diff is the same.", "The default branch of the remote.", "Rebase is fine on a branch you own. It is hostile on a branch other people have based work on."),
    q("cicd-git", "hard", "A signed tag and a floating branch name differ for a release because:", "The tag can name one commit. A branch moves when someone pushes.", "Tags move by default and branches cannot.", "Signatures cover the working tree, not the commit.", "Git cannot sign a tag.", "Release from a tag or a commit you recorded. Do not release from a branch tip that can still move."),
    q("cicd-actions", "medium", "A job needs to deploy to cloud without a long-lived access key. What should it use?", "OIDC federation, so the workflow gets a short-lived token for one role.", "A cloud access key in the repository secrets, with admin rights, reused by every repo.", "The runner's instance profile from an untrusted pull request, with no subject check.", "A key checked into the workflow YAML.", "Federate the identity and constrain the subject to the repo and the branch you trust."),
    q("cicd-actions", "hard", "pull_request_target runs with the base repository's secrets and a checkout of the pull request can run its code. Why is that dangerous?", "Untrusted code from the pull request executes in a context that can see secrets.", "pull_request_target has no token.", "It only runs on tags.", "Secrets are not available to any GitHub event.", "Use pull_request for untrusted code. Keep secrets off workflows that execute the PR's own scripts."),
    q("cicd-actions", "easy", "A workflow file lives in:", ".github/workflows in the repository that runs it.", "The runner's /etc.", "The container registry.", "Kubernetes only.", "The file is code. Review it like the deploy it performs."),
    q("cicd-actions", "medium", "actions/checkout@v4 is convenient and weaker than a pin because:", "The tag can move to a new commit you have not read. A SHA pin does not.", "A SHA changes every time the action's default branch changes, so it is less stable. The SHA is the stable one.", "Tags are immutable on GitHub.", "Pinning breaks permissions.", "Pin third-party actions to a commit if the workflow can deploy or read secrets."),
    q("cicd-jenkins", "medium", "A Jenkins controller and its agents divide the work as:", "The controller schedules and holds configuration. The agent runs the build.", "The agent stores credentials and the controller executes compilers.", "They must be the same machine.", "Agents cannot be ephemeral.", "Keep the controller small and the agents replaceable. A persistent agent accumulates secrets and toolchains."),
    q("cicd-jenkins", "easy", "A Jenkinsfile in the repo is better than a job clicked together in the UI because:", "The pipeline is reviewed and versioned with the code.", "The UI cannot run pipelines.", "Jenkinsfile disables credentials.", "The UI job is automatically reproducible.", "If it is not in git, you cannot review the deploy."),
    q("cicd-jenkins", "medium", "Credentials in a Jenkins job should be:", "Looked up from the credentials store and masked, scoped to the jobs that need them.", "Printed in the log so the next person can debug.", "Stored in the job description.", "The same global admin token for every folder.", "Scope and mask. A folder store is narrower than the global one."),
    q("cicd-jenkins", "hard", "A shared agent just built an untrusted branch and will build main next. What is the risk?", "Files, tokens, and a poisoned tool cache from the untrusted build can affect main.", "Agents wipe themselves on every job by default. They do not, unless you made them ephemeral.", "Branches cannot share an agent.", "The risk is only cosmetic.", "Use ephemeral agents, or isolate untrusted jobs from the agent that produces releases."),
    q("cicd-artifacts", "medium", "You rebuilt version 1.4.2 from a branch that moved and pushed it over the old artifact. What broke?", "The version no longer names one set of bytes. Anyone who already verified 1.4.2 verified something else.", "Versions are supposed to float.", "Registries reject overwrites, so this cannot happen. Many will not.", "The git tag is the artifact.", "Publish an immutable version. A new commit is a new version."),
    q("cicd-artifacts", "easy", "An artifact repository such as Nexus exists to:", "Hold the built outputs the deploy consumes, separate from the source repo.", "Replace git.", "Run the production pods.", "Store only container logs.", "Source is git. The thing you run is the artifact."),
    q("cicd-artifacts", "medium", "Promotion between staging and production should move:", "The same digest or the same immutable artifact, not a new build from the same branch name.", "A fresh build of main, which might not match what you tested.", "The working tree of a laptop.", "A tag that still points at a moving branch.", "If you rebuild, you did not promote. You tested one thing and shipped another."),
    q("cicd-artifacts", "hard", "A container image and a Helm chart and a git commit all claim to be the release. What has to agree?", "The chart values pin the image digest, and the git commit records that chart version.", "Only the git branch name. Digests are optional.", "The image tag latest, the chart without a version, and today's main.", "They cannot be related.", "One release, one set of ids, written down."),
    q("cicd-promotion", "medium", "A manual approval gate before production is useful when:", "A human has to accept the already-built artifact, not when a human rebuilds it by hand.", "You want production to build from a different Dockerfile.", "Approvals replace tests.", "The gate rebuilds from main after approval, picking up new commits.", "Approve the thing you tested. Do not let the gate become a second, untested build."),
    q("cicd-promotion", "easy", "Staging and production should differ by:", "Config and scale, not by a different commit of the application.", "The application source.", "The language.", "Whether tests ran.", "If staging is a different build, it did not rehearse the release."),
    q("cicd-promotion", "hard", "A rollback should be:", "A deploy of a previously known artifact, which you still have.", "A revert commit that is built for the first time during the incident.", "A kubectl delete of the namespace.", "Impossible if you use GitOps.", "Keep the old artifact. A rollback that requires a rebuild is not a rollback."),
    q("cicd-promotion", "medium", "Environment-specific config belongs:", "Outside the immutable artifact, injected at deploy.", "Baked into the image as a build arg for each environment, producing several 'same' versions.", "In the application source as a production password.", "In the git history of a public repo.", "One artifact, many configs. Secrets stay in the secret store."),
    q("cicd-runners", "medium", "A self-hosted runner on a production network, shared by every repository in the org, is:", "A pivot. Untrusted workflows become code running next to production.", "The recommended default for public forks.", "Isolated per job even when the disk persists.", "Unable to read environment variables.", "Isolate runners. Ephemeral is better than a long-lived machine full of caches and tokens."),
    q("cicd-runners", "easy", "GitHub-hosted runners are a better default for a public repository because:", "The untrusted job does not land on your network.", "They are faster than any self-hosted machine.", "They can reach your private subnets automatically.", "They store your production kubeconfig.", "Bring a self-hosted runner only when the job needs your private network, and then scope it."),
    q("cicd-runners", "hard", "A runner's cloud role can deploy, and the workflow checks out a pull request. What should be true of that role?", "Only workflows you trust, on branches you protect, can assume it. A fork's pull request must not.", "Any workflow in the repo can assume it, including forks.", "Roles cannot be limited by repository.", "The role is safe because the runner is in a private subnet.", "The identity of the workflow is part of the security boundary."),
    q("cicd-runners", "medium", "Caches on a shared runner are a supply-chain issue because:", "A previous job can poison a dependency cache the next job trusts.", "Caches are signed by the dependency author always.", "Caches live in the registry and are immutable.", "Only the compiler uses caches, never package managers.", "Key the cache tightly or rebuild on a clean agent for the release job."),
    q("cicd-supply", "medium", "Pinning an action or a base image by digest helps because:", "A moved tag cannot change what you run without a review of the new digest.", "Digests are easier to remember.", "Tags cannot be scanned.", "A digest includes the Kubernetes manifests.", "Update digests on purpose, with a diff, not because a tag moved overnight."),
    q("cicd-supply", "medium", "A dependency bot opened a pull request that bumps a library. What do you still owe?", "A review and a test run. The bot does not know if the new version is safe for this program.", "Nothing. Bots only open safe upgrades.", "A production deploy from the bot's branch with no review.", "Disabling the test workflow for bot authors.", "The bot is a patch proposal. Your pipeline is the gate."),
    q("cicd-supply", "hard", "A malicious version of a small library ran in your build. The build had the deploy key. What failed?", "The build environment was allowed to deploy, so code you did not write had your production credentials.", "Lockfiles, which would have made the install unreproducible. The lockfile is what you wanted.", "The registry, which should execute install scripts with your cloud role.", "Nothing. Install scripts cannot use environment variables.", "Split fetch, build, and deploy credentials. A build does not need to be able to ship."),
    q("cicd-supply", "easy", "An SBOM attached to a release is:", "A list of what went into the artifact, so you can answer 'are we affected' when a CVE appears.", "A vulnerability scan result. Related, not the same.", "The runtime firewall.", "The git blame.", "Generate it from the build you actually shipped."),
    q("iac-workflow", "medium", "The usual Terraform change sequence is:", "fmt and validate, plan, read the plan, then apply that plan.", "apply with no plan, because plan cannot show destroys.", "edit state by hand, then apply.", "Destroy before every plan.", "The plan is the review. Apply what you reviewed, not a new plan you have not read."),
    q("iac-workflow", "easy", "terraform fmt and validate catch:", "Style, and whether the configuration is internally consistent. They do not prove the cloud will accept the change.", "The production impact.", "A replacement of the plan step.", "IAM mistakes in the live account.", "Validation is local. The plan is what talks about real resources."),
    q("iac-workflow", "medium", "A module is called twice with different variables. That is:", "Two instances of the same pattern, which is the point of a module.", "Illegal. Modules can be used once.", "A state corruption.", "The same resource address twice, always.", "Addresses include the module instance. The duplication you want is in the module source, not in copy-paste."),
    q("iac-workflow", "hard", "You need a one-off exception and someone suggests terraform apply -target on the production stack. What is the cost?", "The rest of the desired state is not reconciled, so the next full apply can surprise you.", "Target is required for every apply.", "Target refreshes state and changes nothing.", "Target disables the provider.", "Use it as a scalpel in an incident, then follow with a full plan so the exception does not become drift."),
    q("iac-state", "medium", "Terraform state is:", "The mapping from your config addresses to real resource ids. It is not a backup of the cloud.", "A log of kubectl commands.", "Optional. Apply works without it.", "Safe to commit to a public repo because it has no secrets. It often does.", "Store it remotely, lock it, and restrict who can read it."),
    q("iac-state", "hard", "Two people apply at the same time against one state with no lock. What can happen?", "Both think they own the next change. One overwrites the other's record of reality.", "The state file merges cleanly like git.", "Terraform always locks locally even on object storage. You have to configure the lock.", "Nothing. Apply is serialized by the cloud.", "Use a lock on the backend. A missing lock is how two applies corrupt the map."),
    q("iac-state", "medium", "A resource was created by hand and you want Terraform to own it without recreating it. What is the operation?", "Import it, so state learns the existing id, then plan until the diff is empty.", "Delete it and let apply recreate it.", "Remove the resource from the configuration and leave state pointing at it.", "terraform refresh, which adopts resources. Refresh only updates attributes of things already in state.", "Import, then make the config match. The first plan after a bad import is when you find out it would replace the resource."),
    q("iac-state", "easy", "Why are separate states per environment a good default?", "A bad plan in dev cannot destroy production, and the blast radius of the state file stays smaller.", "State files have a size limit of one resource.", "Terraform cannot use more than one provider.", "It makes locking unnecessary.", "Split by blast radius. A single global state is a single global mistake."),
    q("iac-modules", "medium", "A module output is:", "A value the caller can use, such as an id the rest of the stack needs.", "A cloud resource the module always destroys.", "The same as an input variable.", "Stored only in the module's README.", "Outputs are the module's return values. Inputs are the arguments."),
    q("iac-modules", "easy", "You copy a module from a git tag rather than a branch because:", "The tag can stay put. A branch tip will change under you.", "Tags are always newer than branches.", "Branches cannot hold Terraform.", "A tag disables variables.", "Pin the source. Review the bump."),
    q("iac-modules", "hard", "A module rename moved a resource address and Terraform plans to destroy and recreate a database. What avoids the destroy?", "A moved block, or state mv, so the address change is a rename and not a replacement.", "Deleting the state.", "Changing the provider.", "There is no way. Renames always destroy.", "Addresses are identity to Terraform. Tell it the resource moved."),
    q("iac-modules", "medium", "A child module hard-codes a region. Why is that a problem for the caller?", "The caller cannot reuse it in another region without forking.", "Hard-coded regions apply faster.", "Modules are not allowed to have variables.", "The region in the provider is ignored.", "Regions, names, and sizes are inputs. Hard-coding is how a module becomes a one-off script."),
    q("iac-plan", "medium", "A plan says 1 to destroy and 1 to create for a resource you only renamed in the console. What is Terraform telling you?", "It cannot update that field in place, or it has lost track of the object, so it intends to replace it.", "Destroy and create means a tag change with no downtime.", "Plans cannot show destroys.", "The numbers are estimates and apply will not destroy.", "Read a replace. It is downtime and data loss if the resource is a database."),
    q("iac-plan", "easy", "terraform plan -out and apply of that file matters because:", "You apply the plan you read, not a newly generated one that might include someone else's change.", "The file is human-readable JSON you can edit.", "It skips the provider.", "It updates state without calling the API.", "A plan that sits while others change the world is not the world you apply an hour later unless you saved it and nothing else applied."),
    q("iac-plan", "hard", "The plan is empty and production is still wrong. What can explain it?", "Drift that refresh did not surface, a resource Terraform does not manage, or you are in the wrong workspace or state.", "An empty plan always means the cloud matches your wishes.", "Empty plans roll back the last apply.", "You are in the right state because the directory name matches the environment. Not by itself.", "Check the workspace, the backend, and whether the broken thing is even in this configuration."),
    q("iac-plan", "medium", "A variable marked sensitive still appears in state. What did sensitive change?", "Whether the CLI prints it. Not whether it is stored.", "It encrypts the state with a key you do not have to manage.", "It keeps the value out of state.", "It hashes the value before the provider sees it.", "Sensitive is a display control. The state and the cloud still have the value. Protect those."),
    q("iac-policy", "medium", "Checkov, tfsec, or Conftest in a pipeline are there to:", "Fail a change that violates a rule before apply. They do not replace the plan review.", "Apply the Terraform for you.", "Replace IAM in the cloud.", "Encrypt state.", "Policy as code catches a public bucket or an open security group in the diff, while the author is still at the keyboard.", AWESOME, "https://github.com/bridgecrewio/checkov"),
    q("iac-policy", "easy", "A policy failure on a security group that allows 0.0.0.0/0 to SSH is:", "A find you wanted, unless this path is a deliberate bastion with a tighter rule you should encode as an exception.", "Always a false positive.", "Impossible to waive.", "A Kubernetes issue.", "Write the exception narrowly if it is real. Do not turn the check off globally."),
    q("iac-policy", "medium", "Sentinel or OPA attached to a Terraform run differs from a linter on the laptop because:", "It can be a gate the apply cannot skip.", "It edits state.", "It only works offline.", "It replaces the provider credentials.", "A laptop linter is advice. A gate is how the rule survives a hurry."),
    q("iac-policy", "hard", "The policy lets a plan through and the cloud still ends up with a public bucket. How?", "Someone changed it outside Terraform, or the policy did not cover the attribute that was set.", "Policy tools reconfigure the cloud continuously.", "A passed policy deletes public access later.", "State cannot represent a bucket ACL.", "Policy on the plan does not watch the console. Pair it with a cloud scan for drift."),
    q("iac-ansible", "medium", "Ansible and Terraform split the job as:", "Terraform tends to create the infrastructure. Ansible tends to configure what is already there, repeatedly and idempotently.", "They are interchangeable names for one tool.", "Ansible stores a state file of cloud ids and Terraform does not.", "Terraform cannot call a cloud API.", "Use each for the loop it is good at. Driving both at the same resource without a boundary makes two sources of truth."),
    q("iac-ansible", "easy", "An Ansible task that is idempotent can be run twice and:", "Leaves the machine in the desired state without a second, different change.", "Appends a duplicate line every time.", "Always reboots.", "Fails the second time by design.", "Idempotent means the second run is a no-op when the world already matches."),
    q("iac-ansible", "medium", "Ansible Vault is for:", "Encrypting secrets inside the automation repo, with a password that is not also in that repo.", "Replacing HashiCorp Vault only, with the same API.", "Encrypting Terraform state automatically.", "Hiding playbook syntax errors.", "The encrypted file can live in git. The password cannot."),
    q("iac-ansible", "hard", "A playbook copies a secret to a world-readable file in /tmp and deletes it at the end. What is still wrong?", "The secret hits the disk and may land in a crash, a backup, or a process list before the delete task.", "Ansible cannot copy files.", "The delete task runs even when the play fails, always.", "Temporary files are not readable by other users regardless of mode.", "Use a secret store or a file mode and a no-log task. Do not parade the secret through /tmp."),
    q("iac-secrets", "medium", "A cloud credential in terraform.tfvars committed to git is:", "A leaked credential. Rotate it. tfvars is a common accident.", "Safe because git ignores capital letters.", "Encrypted by git.", "Invisible in pull requests.", "Keep secrets in the secret manager or a CI secret. Pass them in at run time."),
    q("iac-secrets", "easy", "SOPS lets you:", "Encrypt specific values in a YAML or JSON file and still diff the rest in git.", "Run containers.", "Replace IAM.", "Scan container images.", "The file can be reviewed. The value cannot be read without the key."),
    q("iac-secrets", "hard", "External Secrets Operator or a CSI driver exists so that:", "The cluster fetches the secret from a manager at runtime instead of you copying it into a manifest.", "Secrets are stored in ConfigMaps more safely.", "Git becomes the secret store.", "The kubelet stops using service accounts.", "The source of truth stays in the manager. The manifest only says which secret to fetch."),
    q("iac-secrets", "medium", "Sealed Secrets or an encrypted git payload is a reasonable choice when:", "You want GitOps to hold a ciphertext the cluster can decrypt, and not the plaintext.", "You want every developer to read production passwords in the pull request.", "You do not have a cluster.", "The plaintext must appear in the diff for review.", "Review the fact that a secret changed. Do not review the secret."),
    q("cloud-iam", "medium", "A human and a workload should not share an access key because:", "You cannot revoke one without breaking the other, and the audit trail does not say who acted.", "Keys are safer when shared.", "IAM allows only one key per account, so sharing is required.", "Workloads cannot use roles.", "Give the human SSO and the workload a role it assumes. No long-lived shared key."),
    q("cloud-iam", "medium", "An instance profile or workload identity is better than a key on disk because:", "The credential is short-lived and tied to the compute, and there is no secret to commit.", "It grants administrator by design.", "It cannot be scoped.", "It disables CloudTrail.", "Scope the role to the API calls that instance actually makes."),
    q("cloud-iam", "easy", "Least privilege for a deploy role means:", "The role can perform the deploy and cannot administer the account.", "The role is AdministratorAccess so deploys never fail.", "The role has no permissions and the deploy uses a user's password.", "One role is shared with the data science laptops.", "Start from the API calls the pipeline makes. Add those. Do not start from admin and hope."),
    q("cloud-iam", "hard", "A resource policy on a bucket and an identity policy on a role both exist. Access is allowed when:", "Both sides allow it, and neither denies it. An explicit deny wins.", "The resource policy is ignored if the caller is in the same account, always.", "Only the identity policy matters.", "Only the bucket policy matters for IAM users.", "When something is denied and you expected allow, read both documents and look for an explicit deny."),
    q("cloud-vpc", "medium", "A public subnet is public because:", "Its route table sends 0.0.0.0/0 to an internet gateway, and the instance has a public address.", "Its name contains the word public. Routes are irrelevant.", "It uses a 10.0.0.0 address.", "It has no network ACL.", "The route and the address are the definition. A private address with a route to the IGW still needs a public path to be reachable."),
    q("cloud-vpc", "easy", "A VPC peering or a transit gateway connects:", "Private networks so instances can route to each other's private addresses, without making them public.", "Every instance to the internet.", "IAM roles.", "Only DNS.", "Add routes both ways for the prefixes you actually need. Peering is not transitive in the classic AWS form."),
    q("cloud-vpc", "medium", "You put a database in a private subnet and a bastion in a public subnet. What did you gain?", "The database has no public route. Administration goes through a host you can lock down.", "The database is unreachable from the application too.", "The bastion is unnecessary if the database is private.", "Private subnets cannot accept connections from other subnets in the VPC.", "Security groups still have to allow the app tier. Private does not mean isolated from the VPC."),
    q("cloud-vpc", "hard", "A NAT gateway is in one availability zone and that zone fails. What fails with it?", "Outbound internet from private subnets whose default route points only at that NAT.", "Inbound traffic to a public load balancer in another zone.", "IAM.", "Objects already stored in a regional bucket, by themselves.", "A single NAT is a single egress path. Multi-AZ egress costs more and fails less."),
    q("cloud-sg", "medium", "A security group is stateful. You allow inbound 443. What do you not have to add?", "An outbound rule for the return packets of that same connection.", "A route to the client.", "A listener on 443.", "The instance.", "Statefulness is the difference from a NACL, which needs the return path spelled out."),
    q("cloud-sg", "easy", "0.0.0.0/0 on port 22 in a security group means:", "The entire IPv4 internet may attempt SSH.", "Only your office, because security groups are private.", "SSH is disabled.", "The port is open only for ten minutes.", "Use a VPN, a bastion, or SSM. Do not leave administration on the internet."),
    q("cloud-sg", "hard", "The security group allows the port and the connection still times out. A NACL is on the subnet. What is a likely gap?", "The stateless NACL allows the request and drops the return, or the reverse.", "Security groups override NACLs completely.", "NACLs only affect ICMP.", "Time outs are always the application.", "Check both. A timeout is often a drop, and a drop is often the stateless half."),
    q("cloud-sg", "medium", "Referencing another security group as the source, instead of a CIDR, is better because:", "Traffic is allowed from whatever currently has that group, even if the IPs change.", "The group reference disables egress.", "CIDRs are more precise for autoscaling members.", "Group references are not supported.", "Autoscaling changes IPs. The group membership is the stable name."),
    q("cloud-compute", "medium", "An autoscaling group replaces an instance that fails its health check. What must be true for that to be safe?", "The instance is disposable. State lives elsewhere.", "The instance's disk is the only copy of the database.", "User data fetches a secret and writes it to a world-readable file.", "The health check is a ping, while the process is dead. That would not replace it.", "Treat the instance as cattle. A health check that matches the real failure is part of the design."),
    q("cloud-compute", "easy", "User data is:", "A script or config the instance runs on boot. It is not a secret store.", "The IAM policy.", "The disk snapshot.", "A Kubernetes manifest.", "Logs of user data end up in cloud logs. Do not put a long-lived password in them."),
    q("cloud-compute", "medium", "ECS or a VM and Kubernetes can all run a container. What is the platform choice really about?", "How much of scheduling, identity, and rollout you want to operate yourself.", "Containers only run on Kubernetes.", "VMs cannot run containers.", "ECS cannot use IAM.", "Pick the control plane your team can run at 2 a.m."),
    q("cloud-compute", "hard", "You baked a secret into an AMI. What is true after you rotate the secret in the manager?", "Every instance launched from that AMI still has the old secret until you bake again and replace them.", "AMIs refetch user data secrets on every API call.", "Deregistering the AMI wipes disks already running.", "Snapshots cannot contain files.", "Secrets in images outlive the rotation. Inject them at boot."),
    q("cloud-lb", "medium", "An application load balancer and a network load balancer differ because:", "The application one understands HTTP and can route on host and path. The network one forwards TCP or UDP.", "The network one terminates TLS and routes on URL. That is the application one, unless you added TLS features deliberately.", "They both require Kubernetes.", "The application one cannot have a health check.", "Choose from the protocol you need to see."),
    q("cloud-lb", "easy", "A health check on /healthz that the app does not serve will:", "Mark every target unhealthy and stop sending users.", "Be ignored.", "Increase capacity.", "Replace the security group.", "The check has to match a path the app actually answers."),
    q("cloud-lb", "medium", "Sticky sessions on a load balancer hurt when:", "One client is actually a single NAT full of users, so one target gets the whole office.", "You have one target.", "The protocol is UDP and you enabled HTTP cookies. Cookies are not the UDP mechanism.", "Health checks are on.", "Affinity is a workaround for state in the process. Moving the state out avoids it."),
    q("cloud-lb", "hard", "TLS terminates at the load balancer and the backend only sees HTTP. What do you still verify?", "The backend is not also reachable directly from the network, skipping the balancer and the TLS.", "Nothing. HTTP inside the VPC is always fine.", "The certificate is installed on every client.", "The backend must present the same public certificate or the balancer will not work. Not when it is terminating.", "A private path that bypasses the balancer bypasses the policy you thought you had."),
    q("cloud-registry", "medium", "A cloud container registry such as ECR is where:", "Images live, with IAM deciding who can push and pull, separate from the cluster's RBAC.", "Kubernetes Secrets are stored by default.", "Terraform state must live.", "Only public images can be pushed.", "The node role needs pull. The CI role needs push. Those are different principals."),
    q("cloud-registry", "easy", "Scanning an image on push tells you:", "Known vulnerabilities in the layers at that moment. It does not patch them.", "The image is safe to run forever.", "The Dockerfile is linted.", "The cluster will refuse the image. Not unless you also enforce that.", "Scan is a signal. Admission or a rebuild is the control."),
    q("cloud-registry", "medium", "You want production to pull only from your registry, not from Docker Hub. What enforces it?", "Network egress, an admission policy, or a runtime policy. A team convention does not.", "The registry's existence.", "A Dockerfile comment.", "IAM on the registry, which cannot see pulls from somewhere else.", "Block the other path. Otherwise the next manifest will use a public tag."),
    q("cloud-registry", "hard", "Immutable tags on the registry help because:", "A push cannot quietly replace the bytes behind a tag the cluster already references.", "Tags become digests.", "Immutability encrypts the layers.", "It disables deletion.", "Combine it with a digest pin if the tag is a version you will trust."),
    q("cloud-object", "medium", "Object storage for Terraform state needs:", "Versioning, encryption, restricted IAM, and a lock. Public access blocked.", "A public-read ACL so the team can debug it.", "No versioning, so the file stays small.", "The same bucket as the public website.", "State contains ids and often secrets. Treat the bucket as production data."),
    q("cloud-object", "easy", "A bucket and an object differ because:", "The bucket is the container and the policy boundary. The object is one file inside it.", "They are the same ARN.", "Objects can exist without a bucket.", "Buckets are regional and objects are always global with no home region. The bucket has a region or a location constraint.", "Block public access at the bucket. One object ACL should not be the only control."),
    q("cloud-object", "hard", "You enabled versioning after a ransomware-style overwrite. What do you get for the future, not the past?", "Later overwrites keep the previous bytes as a version. The overwrite that already happened is not undone by turning versioning on.", "Versioning restores every historical object that existed before you enabled it.", "Versioning prevents deletes.", "Versioning publishes the bucket.", "Turn it on before the incident if you want the previous copy."),
    q("cloud-object", "medium", "A lifecycle rule moves old build artifacts to cold storage. What must you not do to the current release?", "Expire it. The artifact you may roll back to has to stay readable.", "Encrypt it.", "Put it in a prefix.", "Name it with a version.", "Lifecycle is a cost tool. Exclude the versions your rollback story needs."),
    q("cloud-regions", "medium", "An availability zone and a region differ because:", "A region is a group of zones. A zone is a failure domain with its own power and network inside that region.", "They are synonyms.", "A zone spans continents.", "A region is a single data center.", "One zone failing should not take a regional service you designed to survive it. A single-AZ database will."),
    q("cloud-regions", "easy", "Running a copy of a service in a second region helps when:", "You can actually fail over data and DNS, not when the second copy is an empty cluster.", "The second region shares the first region's control plane failure.", "You want lower latency on the same city only. That is a zone or an edge, not automatically a region.", "IAM is regional and cannot be duplicated. Identity is often global. Know which control is.", "A region pair is a project: data, identity, and the switch. A second VPC with no data is a diagram."),
    q("cloud-regions", "hard", "The managed database is regional and the app is multi-AZ. The database fails over. What do the app instances see?", "A short break, then the same endpoint, if they reconnect. They do not each fail over independently.", "Nothing. Multi-AZ apps do not notice a database failover.", "Each AZ has its own independent primary.", "The endpoint DNS name changes to the AZ name.", "Test reconnects. A failover that your connection pool cannot survive is still an outage."),
    q("cloud-regions", "medium", "Putting the only NAT, the only bastion, and the only CI runner in one zone means:", "That zone is your real availability, whatever the slide says.", "The region is highly available.", "Zones are decorative.", "The load balancer fixes it.", "Count the things that exist once. Those are the failure domains."),
    q("obs-logs", "medium", "A request id in every log line is useful because:", "You can collect one request across services. Without it you have timestamps and a guess.", "It replaces traces.", "It makes the log smaller.", "It is the HTTP status.", "Generate it at the edge and pass it. Searching by time across five services is how incidents get long."),
    q("obs-logs", "easy", "stdout from a container is a better default than a file in the container because:", "The node or the platform can ship it without you execing in to read a file that vanishes with the container.", "Files are shipped automatically and stdout is dropped.", "stdout cannot be structured.", "The kubelet deletes stdout.", "Log to stdout unless you have a reason. Then make sure something reads it."),
    q("obs-logs", "medium", "A log pipeline dropped messages during a deploy. What did you fail to budget?", "Disk or memory at the shipper, and a decision about whether you drop, block, or sample.", "The certificate expiry of the API server.", "The number of Kubernetes namespaces, which caps log volume.", "CPU requests, which do not affect logging.", "Logging has a failure mode. Decide it before the incident produces more logs than the pipeline can hold."),
    q("obs-logs", "hard", "You logged a full HTTP header set and now a token is in the log store. What is true?", "The token is compromised to everyone who can read logs. Rotate it. Redact next time.", "Logs are encrypted so the token is safe.", "Retention does not matter.", "Tokens in headers are automatically masked by every agent.", "Treat log access like secret access. Do not write secrets in the first place."),
    q("obs-metrics", "medium", "A Prometheus label with a user id on every request will:", "Explode cardinality and the memory of the server.", "Make queries faster.", "Be required for a RED dashboard.", "Replace logs.", "Labels are an index. Unbounded labels are an outage."),
    q("obs-metrics", "easy", "A counter and a gauge differ because:", "A counter only goes up, aside from a restart. A gauge moves up and down.", "A gauge is always an integer and a counter is a string.", "They are scraped differently.", "A counter resets every scrape.", "Use a counter for requests. Use a gauge for queue depth or temperature."),
    q("obs-metrics", "medium", "An average latency hides:", "The slow tail. A histogram or a percentile is what tells you the bad requests.", "Nothing. The average is the SLO.", "The request rate.", "Errors.", "A p99 and a count tell an incident story. An average can stay flat while a slice of users time out."),
    q("obs-metrics", "hard", "USE for a resource and RED for a service mean:", "Utilization, saturation, errors for the resource. Rate, errors, duration for the service.", "The same three graphs for both.", "User, system, and disk.", "They are log levels.", "Pick the method that matches the thing. A CPU and an HTTP API are not the same shape."),
    q("obs-traces", "medium", "A trace is more than a log because:", "It connects spans across processes with a shared trace id, including timing.", "It replaces metrics.", "It is a single line.", "It cannot cross a network.", "You want one trace when a request is slow and you do not know which hop."),
    q("obs-traces", "easy", "Sampling traces exists because:", "Recording every span of every request can cost more than the request.", "Traces are useless at low volume.", "The collector requires sampling of 100 percent.", "Sampling makes them more accurate.", "Sample enough to debug. Do not assume you can keep everything."),
    q("obs-traces", "medium", "A span without the parent id from the incoming request is:", "A broken trace. The hop looks like a new, unrelated request.", "A metric.", "A log level.", "A health check.", "Propagate the trace context. The header you forgot is why the picture stops at the proxy."),
    q("obs-traces", "hard", "You have traces and no metrics. What is painful?", "Alerting and capacity. Traces explain one request. They are a poor counter of all requests.", "Nothing. Traces include a complete RED dashboard for free.", "Deploying.", "Authentication.", "Keep a cheap metric for the alert and a trace for the example."),
    q("obs-prometheus", "medium", "Prometheus scrapes. The application:", "Exposes a metrics endpoint. Prometheus pulls it. The app does not push, in the basic setup.", "Must ship metrics to a vendor directly.", "Writes to a local CSV that Prometheus tails.", "Uses syslog.", "If the target is down, the scrape fails and you see the gap. That is a feature."),
    q("obs-prometheus", "easy", "Grafana in front of Prometheus is:", "The dashboard. Prometheus is the store and the query language.", "A second database that scrapes targets itself by default.", "An alert router only.", "A log store.", "Do not expect Grafana to have the samples if Prometheus never scraped them."),
    q("obs-prometheus", "medium", "Alertmanager's job is:", "To route, group, and silence alerts. The alert rule lives in Prometheus.", "To scrape targets.", "To store raw logs.", "To deploy Helm charts.", "A rule with no route is a rule nobody sees. A route with no rule is silence."),
    q("obs-prometheus", "hard", "A recording rule helps when:", "The same expensive query is used on every dashboard and you would rather compute it once.", "You want to drop labels to increase cardinality.", "You need traces.", "The scrape is failing.", "Record the aggregation you always ask for. Do not record every raw series again."),
    q("obs-otel", "medium", "OpenTelemetry is the point where:", "The application emits signals in a vendor-neutral way, and a collector exports them to wherever you store them.", "You must run Prometheus and nothing else.", "Logs are forbidden.", "The SDK replaces the application.", "Instrument once. Change the exporter when you change vendors."),
    q("obs-otel", "easy", "A collector in the path lets you:", "Batch, filter, and fan out, without shipping a vendor SDK in every binary.", "Skip instrumentation.", "Remove the need for a trace id.", "Encrypt the disk.", "The collector is a process you operate. It is also the place a bad config drops data."),
    q("obs-otel", "medium", "You send traces to one vendor and metrics to Prometheus. OTel fits because:", "Different exporters can sit behind one instrumentation.", "It requires a single backend.", "It cannot do metrics.", "Prometheus cannot scrape an OTel collector.", "The pipeline is allowed to fork. The app should not have to."),
    q("obs-otel", "hard", "A collector queue fills and the collector is configured to drop. What do you lose first, and what should you have paged on?", "New telemetry, while the app keeps running. Page on the collector's own queue and export failures.", "The application process, which blocks forever by default in every SDK.", "Nothing. A full queue retries forever in the application thread always.", "Only traces older than a year.", "The pipeline's failure mode is a decision. Watch the pipeline, not only the app."),
    q("obs-alerts", "medium", "An alert that fires whenever CPU is over 80 percent for a minute is weak because:", "CPU is a cause, not a symptom. Users may be fine, and you will learn to ignore it.", "CPU cannot be measured.", "Alerts should only use logs.", "80 percent is always an outage.", "Alert on error rate, latency, or saturation that means the service is failing its job."),
    q("obs-alerts", "easy", "A good alert has:", "A name that says what is wrong, and a link or a sentence that says what to do next.", "Only a metric name.", "A threshold copied from another company.", "No owner.", "If it does not change what a human does, it is a chart, not an alert."),
    q("obs-alerts", "hard", "You silenced a noisy alert during an incident and forgot. What is the durable fix?", "A silence with an owner and an expiry, and a ticket to fix the rule. An infinite silence is a deleted alert.", "Delete the metric.", "Raise the threshold until it never fires, including during the real outage.", "Turn off the receiver.", "Silence is a pause. The rule still needs to be true."),
    q("obs-alerts", "medium", "Paging someone for a dev cluster and for production on the same route causes:", "Fatigue. Production pages get ignored because dev is loud.", "Better coverage.", "Lower latency.", "Fewer false positives automatically.", "Separate the routes. The severity is part of the alert."),
]
